class Solution:
    def maximumValueSum(self, board: list[list[int]]) -> int:
        m, n = len(board), len(board[0])
        if m > n:
            board = [list(row) for row in zip(*board)]
            m, n = n, m
        NEG = float('-inf')
        best = NEG
        for i in range(m):
            for j in range(i + 1, m):
                for k in range(j + 1, m):
                    dp = [NEG] * 8
                    dp[0] = 0
                    for c in range(n):
                        vals = (board[i][c], board[j][c], board[k][c])
                        nd = dp[:]
                        for mask in range(8):
                            if dp[mask] == NEG:
                                continue
                            for b in range(3):
                                if not mask >> b & 1:
                                    nm = mask | 1 << b
                                    if dp[mask] + vals[b] > nd[nm]:
                                        nd[nm] = dp[mask] + vals[b]
                        dp = nd
                    best = max(best, dp[7])
        return best

