class Solution {
public:
    int maximumValueSum(vector<vector<int>>& board) {
        int m = board.size(), n = board[0].size();
        if (m > n) {
            vector<vector<int>> t(n, vector<int>(m));
            for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) t[j][i] = board[i][j];
            board = t; swap(m, n);
        }
        long long best = LLONG_MIN;
        for (int i = 0; i < m; i++)
            for (int j = i + 1; j < m; j++)
                for (int k = j + 1; k < m; k++) {
                    vector<long long> dp(8, LLONG_MIN / 2);
                    dp[0] = 0;
                    for (int c = 0; c < n; c++) {
                        int vals[3] = {board[i][c], board[j][c], board[k][c]};
                        auto nd = dp;
                        for (int mask = 0; mask < 8; mask++) {
                            if (dp[mask] <= LLONG_MIN / 4) continue;
                            for (int b = 0; b < 3; b++)
                                if (!(mask >> b & 1))
                                    nd[mask | 1 << b] = max(nd[mask | 1 << b], dp[mask] + vals[b]);
                        }
                        dp = nd;
                    }
                    best = max(best, dp[7]);
                }
        return (int)best;
    }
};

