class Solution {
    public int maximumValueSum(int[][] board0) {
        int m = board0.length, n = board0[0].length;
        int[][] board = board0;
        if (m > n) {
            int[][] t = new int[n][m];
            for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) t[j][i] = board[i][j];
            board = t;
            int tmp = m; m = n; n = tmp;
        }
        long best = Long.MIN_VALUE;
        for (int i = 0; i < m; i++)
            for (int j = i + 1; j < m; j++)
                for (int k = j + 1; k < m; k++) {
                    long[] dp = new long[8];
                    Arrays.fill(dp, Long.MIN_VALUE / 2);
                    dp[0] = 0;
                    for (int c = 0; c < n; c++) {
                        int[] vals = {board[i][c], board[j][c], board[k][c]};
                        long[] nd = dp.clone();
                        for (int mask = 0; mask < 8; mask++) {
                            if (dp[mask] <= Long.MIN_VALUE / 4) continue;
                            for (int b = 0; b < 3; b++)
                                if ((mask >> b & 1) == 0)
                                    nd[mask | 1 << b] = Math.max(nd[mask | 1 << b], dp[mask] + vals[b]);
                        }
                        dp = nd;
                    }
                    best = Math.max(best, dp[7]);
                }
        return (int) best;
    }
}

