var maximumValueSum = function(board0) {
    let board = board0, m = board.length, n = board[0].length;
    if (m > n) {
        board = Array.from({length: n}, (_, j) => Array.from({length: m}, (_, i) => board0[i][j]));
        [m, n] = [n, m];
    }
    const NEG = -Infinity;
    let best = NEG;
    for (let i = 0; i < m; i++)
        for (let j = i + 1; j < m; j++)
            for (let k = j + 1; k < m; k++) {
                let dp = new Array(8).fill(NEG);
                dp[0] = 0;
                for (let c = 0; c < n; c++) {
                    const vals = [board[i][c], board[j][c], board[k][c]];
                    const nd = dp.slice();
                    for (let mask = 0; mask < 8; mask++) {
                        if (dp[mask] === NEG) continue;
                        for (let b = 0; b < 3; b++)
                            if (!(mask >> b & 1))
                                nd[mask | 1 << b] = Math.max(nd[mask | 1 << b], dp[mask] + vals[b]);
                    }
                    dp = nd;
                }
                best = Math.max(best, dp[7]);
            }
    return best;
};
